{
  "name": "fluxo",
  "version": "0.3.0",
  "description": "Passagem de bastão entre máquinas (/handoff) e aviso quando um turno longo termina",
  "author": {
    "name": "Kevin Medeiros"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "longTurnMinutes": {
      "type": "number",
      "title": "Turno longo (minutos)",
      "description": "Avisa quando um turno do fio principal passa deste tempo",
      "default": 3
    },
    "sound": {
      "type": "boolean",
      "title": "Som no fim do turno longo",
      "description": "Toca um som curto (macOS) quando um turno longo termina",
      "default": true
    },
    "speak": {
      "type": "boolean",
      "title": "Falar no fim do turno longo",
      "description": "Diz em voz alta que o turno terminou",
      "default": false
    },
    "autoHandoff": {
      "type": "boolean",
      "title": "Handoff automático",
      "description": "Atualiza .claude/handoff.md depois de cada turno que editou arquivos (fica desligado para não criar arquivos nos repositórios sem você pedir)",
      "default": false
    },
    "handoffPath": {
      "type": "string",
      "title": "Arquivo de handoff",
      "description": "Caminho relativo à raiz do projeto",
      "default": ".claude/handoff.md"
    }
  },
  "license": "MIT",
  "repository": "https://github.com/kevinmedeiros/claude-mods",
  "homepage": "https://github.com/kevinmedeiros/claude-mods#fluxo"
